                             '        driver_free_before = (\n'
                             '            self._driver_free_bytes() if '
                             'envs.VLLM_DEBUG_WORKSPACE else None\n'
                             '        )\n'
                             '        released_bytes = 0\n'
                             '        for name, pointer in '
                             'self._raw_cuda_headroom_pointers.items():\n'
                             '            assert pointer is not None\n'
                             '            _raw_cuda_free(pointer)\n'
                             '            self._raw_cuda_headroom_pointers[name] = '
                             'None\n'
                             '            released_bytes += '
                             'self._raw_cuda_headroom_sizes[name]\n'
                             '        for workspaces in '
                             'self._reclaimable_workspaces.values():\n'
                             '            released_bytes += '
                             'sum(self._workspace_size_bytes(ws) for ws in '
                             'workspaces)\n'
                             '            for ubatch_id in range(self._num_ubatches):\n'
                             '                workspaces[ubatch_id] = None\n'
                             '        self._reclaimable_workspaces_released = True\n'
                             '        if released_bytes:\n'
                             '            torch.accelerator.empty_cache()\n'
                             '\n'
                             '        if envs.VLLM_DEBUG_WORKSPACE and '
                             'released_bytes:\n'
                             '            driver_free_after = '
                             'self._driver_free_bytes()\n'
                             '            if driver_free_before is None or '
                             'driver_free_after is None:\n'
                             '                logger.info(\n'
                             '                    "[WORKSPACE DEBUG] Released %.2f MB '
                             'of reclaimable workspace",\n'
                             '                    released_bytes / _MB,\n'
                             '                )\n'
                             '            else:\n'
                             '                logger.info(\n'
                             '                    "[WORKSPACE DEBUG] Released %.2f MB '
                             'of reclaimable workspace; "\n'
                             '                    "driver free memory %.2f MB -> %.2f '
                             'MB",\n'
                             '                    released_bytes / _MB,\n'
                             '                    driver_free_before / _MB,\n'
                             '                    driver_free_after / _MB,\n'
                             '                )\n'
                             '        return released_bytes\n'
                             '\n'
                             '    def restore_reclaimable_workspaces(self) -> int:\n'
                             '        """Restore released backing tensors at their '
                             'exact profiled sizes."""\n'
                             '        if not self._reclaimable_workspaces_released:\n'
                             '            raise AssertionError("Reclaimable workspaces '
