                              '    cfg.model_config = SimpleNamespace(\n'
                              '        enable_sleep_mode=enable_sleep_mode,\n'
                              '        enable_cumem_allocator=(enable_cumem_allocator '
                              'or enable_sleep_mode),\n'
                              '    )\n'
                              '    cfg._verify_kv_transfer_compat()\n'
                              '    return cfg\n'
