                       '\n'
                       '    def test_batch_eviction_scans_t1_and_t2_once(self):\n'
                       '        """ARC batch eviction must preserve order without '
                       'restarting scans."""\n'
                       '        cpu_manager, arc_policy = self._make_manager(\n'
                       '            num_blocks=256, enable_events=False\n'
                       '        )\n'
                       '        keys = to_keys(list(range(256)))\n'
                       '        cpu_manager.prepare_store(keys, _EMPTY_REQ_CTX)\n'
                       '        cpu_manager.complete_store(keys, _EMPTY_REQ_CTX)\n'
                       '\n'
                       '        cpu_manager.touch(keys[128:], _EMPTY_REQ_CTX)\n'
                       '        arc_policy.target_t1_size = 64\n'
                       '\n'
                       '        protected = {keys[0], keys[2], keys[255]}\n'
                       '        arc_policy.t1[keys[1]].ref_cnt = 1\n'
                       '        arc_policy.t2[keys[254]].ref_cnt = 1\n'
                       '\n'
                       '        num_evictions = 124\n'
                       '        num_t1_evictions = len(arc_policy.t1) - '
                       'int(arc_policy.target_t1_size) + 1\n'
                       '        num_t2_evictions = num_evictions - num_t1_evictions\n'
                       '        t1_order = list(arc_policy.t1)\n'
                       '        t2_order = list(arc_policy.t2)\n'
                       '        expected_t1 = [\n'
                       '            key\n'
                       '            for key, block in arc_policy.t1.items()\n'
                       '            if block.ref_cnt == 0 and key not in protected\n'
                       '        ][:num_t1_evictions]\n'
                       '        expected_t2 = [\n'
                       '            key\n'
                       '            for key, block in arc_policy.t2.items()\n'
                       '            if block.ref_cnt == 0 and key not in protected\n'
                       '        ][:num_t2_evictions]\n'
                       '        expected_t1_scans = t1_order.index(expected_t1[-1]) + '
                       '1\n'
                       '        expected_t2_scans = t2_order.index(expected_t2[-1]) + '
                       '1\n'
                       '\n'
                       '        counting_t1 = _CountingOrderedDict(arc_policy.t1)\n'
                       '        counting_t2 = _CountingOrderedDict(arc_policy.t2)\n'
                       '        arc_policy.t1 = counting_t1\n'
                       '        arc_policy.t2 = counting_t2\n'
                       '\n'
                       '        evicted = arc_policy.evict(num_evictions, protected)\n'
                       '\n'
                       '        assert evicted is not None\n'
                       '        assert [key for key, _ in evicted] == expected_t1 + '
                       'expected_t2\n'
                       '        assert counting_t1.items_yielded == expected_t1_scans\n'
                       '        assert counting_t2.items_yielded == expected_t2_scans\n'
                       '\n'
                       '    def '
                       'test_batch_eviction_falls_back_after_t1_iterator_exhausted(self):\n'
                       '        """An exhausted T1 scan must keep falling back to '
                       'T2."""\n'
                       '        cpu_manager, arc_policy = '
                       'self._make_manager(num_blocks=8, enable_events=False)\n'
                       '        keys = to_keys(list(range(8)))\n'
                       '        cpu_manager.prepare_store(keys, _EMPTY_REQ_CTX)\n'
                       '        cpu_manager.complete_store(keys, _EMPTY_REQ_CTX)\n'
